use xiom.io;

enum Day {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday,
}

fn is_weekend(day: Day) -> Bool {
  return match day {
    Saturday | Sunday => true,
    Monday | Tuesday | Wednesday | Thursday | Friday => false,
  };
}

fn is_school_day(day: Day) -> Bool {
  return match day {
    Monday | Tuesday | Wednesday | Thursday | Friday => true,
    Saturday | Sunday => false,
  };
}

fn main() -> Int {
  io.println(is_weekend(Day.Monday).to_str());
  io.println(is_weekend(Day.Saturday).to_str());
  io.println(is_school_day(Day.Sunday).to_str());
  return 0;
}
